  "Everything: bugs, security, performance, style": { es: "Todo: errores, seguridad, rendimiento, estilo", ar: "كل شيء: الأخطاء والأمان والأداء والأسلوب", zh: "全部：漏洞、安全、性能、风格", sw: "Kila kitu: hitilafu, usalama, utendaji, mtindo", sv: "Allt: buggar, säkerhet, prestanda, stil", de: "Alles: Fehler, Sicherheit, Leistung, Stil", pt: "Tudo: erros, segurança, desempenho, estilo", fr: "Tout : bugs, sécurité, performances, style" },
  "Bugs and crashes only": { es: "Solo errores y bloqueos", ar: "الأخطاء والأعطال فقط", zh: "仅漏洞和崩溃", sw: "Hitilafu na kuanguka tu", sv: "Bara buggar och krascher", de: "Nur Fehler und Abstürze", pt: "Só erros e travamentos", fr: "Seulement les bugs et plantages" },
  "Security problems first": { es: "Primero problemas de seguridad", ar: "مشكلات الأمان أولًا", zh: "安全问题优先", sw: "Matatizo ya usalama kwanza", sv: "Säkerhetsproblem först", de: "Sicherheitsprobleme zuerst", pt: "Problemas de segurança primeiro", fr: "Problèmes de sécurité d'abord" },
  "Beginner mode — explain very simply": { es: "Modo principiante: explica de forma muy sencilla", ar: "وضع المبتدئ — شرح مبسّط جدًا", zh: "新手模式——非常浅显地解释", sw: "Hali ya mwanzo — eleza kwa urahisi sana", sv: "Nybörjarläge — förklara väldigt enkelt", de: "Anfängermodus — ganz einfach erklären", pt: "Modo iniciante — explicar bem simples", fr: "Mode débutant — expliquer très simplement" },
  "Drop code files or a .zip here, or": { es: "Suelta aquí archivos de código o un .zip, o", ar: "أفلت ملفات الشيفرة أو ملف .zip هنا، أو", zh: "将代码文件或 .zip 拖到这里，或", sw: "Dondosha faili za msimbo au .zip hapa, au", sv: "Släpp kodfiler eller en .zip här, eller", de: "Leg Codedateien oder eine .zip hier ab oder", pt: "Solte arquivos de código ou um .zip aqui, ou", fr: "Déposez des fichiers de code ou un .zip ici, ou" },
  "choose files": { es: "elige archivos", ar: "اختر ملفات", zh: "选择文件", sw: "chagua faili", sv: "välj filer", de: "wähle Dateien", pt: "escolha arquivos", fr: "choisissez des fichiers" },
  "Code": { es: "Código", ar: "الشيفرة", zh: "代码", sw: "Msimbo", sv: "Kod", de: "Code", pt: "Código", fr: "Code" },
